/**
 * The conformance scenarios: what every SDK has to agree on, stated once
 * in `crates/otio-sdk-model/src/conformance.rs` and rendered into each
 * language's own tests. A failure here means this SDK disagrees with the
 * others about what the library does.
 *
 * `suite.ts` runs every case in `conformance`, in Node and in Chromium.
 */

import type { Status } from "../src/index.js";
import type { Case, Otio } from "./suite.js";

/** Every scenario, in the order they are written. */
export const conformance: readonly Case[] = [
  // The scenario "building_a_timeline_writes_this_json".
  //
  // Three clips in a video track, built one call at a time, write the same
  // OpenTimelineIO JSON in every language.
  {
    name: "conformance: building_a_timeline_writes_this_json",
    run(api) {
      const timeline = new api.Timeline({ name: "Cut" });
      const stack = timeline.tracks;
      if (!(stack instanceof api.Stack)) {
        throw new Error("timeline's tracks are not a stack");
      }
      const track = new api.Track({ name: "V1", kind: "Video" });
      stack.appendChild(track);
      const a = new api.Clip({ name: "A" });
      a.sourceRange = new api.TimeRange(new api.RationalTime(0.0, 24.0), new api.RationalTime(24.0, 24.0));
      track.appendChild(a);
      const b = new api.Clip({ name: "B" });
      b.sourceRange = new api.TimeRange(new api.RationalTime(24.0, 24.0), new api.RationalTime(48.0, 24.0));
      track.appendChild(b);
      conformanceIs(track.childCount(), 2, "track.childCount()");
      conformanceTime(track.duration(), 72.0, 24.0, "track.duration()");
      conformanceIs(timeline.toJson(4), "{\n    \"OTIO_SCHEMA\": \"Timeline.1\",\n    \"metadata\": {},\n    \"name\": \"Cut\",\n    \"global_start_time\": null,\n    \"tracks\": {\n        \"OTIO_SCHEMA\": \"Stack.1\",\n        \"metadata\": {},\n        \"name\": \"tracks\",\n        \"source_range\": null,\n        \"effects\": [],\n        \"markers\": [],\n        \"enabled\": true,\n        \"color\": null,\n        \"children\": [\n            {\n                \"OTIO_SCHEMA\": \"Track.1\",\n                \"metadata\": {},\n                \"name\": \"V1\",\n                \"source_range\": null,\n                \"effects\": [],\n                \"markers\": [],\n                \"enabled\": true,\n                \"color\": null,\n                \"children\": [\n                    {\n                        \"OTIO_SCHEMA\": \"Clip.2\",\n                        \"metadata\": {},\n                        \"name\": \"A\",\n                        \"source_range\": {\n                            \"OTIO_SCHEMA\": \"TimeRange.1\",\n                            \"duration\": {\n                                \"OTIO_SCHEMA\": \"RationalTime.1\",\n                                \"rate\": 24.0,\n                                \"value\": 24.0\n                            },\n                            \"start_time\": {\n                                \"OTIO_SCHEMA\": \"RationalTime.1\",\n                                \"rate\": 24.0,\n                                \"value\": 0.0\n                            }\n                        },\n                        \"effects\": [],\n                        \"markers\": [],\n                        \"enabled\": true,\n                        \"color\": null,\n                        \"media_references\": {},\n                        \"active_media_reference_key\": \"\"\n                    },\n                    {\n                        \"OTIO_SCHEMA\": \"Clip.2\",\n                        \"metadata\": {},\n                        \"name\": \"B\",\n                        \"source_range\": {\n                            \"OTIO_SCHEMA\": \"TimeRange.1\",\n                            \"duration\": {\n                                \"OTIO_SCHEMA\": \"RationalTime.1\",\n                                \"rate\": 24.0,\n                                \"value\": 48.0\n                            },\n                            \"start_time\": {\n                                \"OTIO_SCHEMA\": \"RationalTime.1\",\n                                \"rate\": 24.0,\n                                \"value\": 24.0\n                            }\n                        },\n                        \"effects\": [],\n                        \"markers\": [],\n                        \"enabled\": true,\n                        \"color\": null,\n                        \"media_references\": {},\n                        \"active_media_reference_key\": \"\"\n                    }\n                ],\n                \"kind\": \"Video\"\n            }\n        ]\n    }\n}\n", "timeline.toJson(4)");
    },
  },
  // The scenario "a_removed_object_s_handle_is_stale".
  //
  // Removing an object makes every handle to it stale: asking it anything fails
  // with a stale-handle status rather than reaching whatever takes its slot
  // next.
  {
    name: "conformance: a_removed_object_s_handle_is_stale",
    run(api) {
      const track = new api.Track({ name: "V1", kind: "Video" });
      const clip = new api.Clip({ name: "doomed" });
      track.appendChild(clip);
      clip.remove();
      conformanceRefused(api, "clip.name", () => clip.name, "staleHandle");
      conformanceIs(track.name, "V1", "track.name");
    },
  },
  // The scenario "naming_an_object_from_another_timeline_is_refused".
  //
  // A call that only names an object refuses one from another timeline before
  // asking the library, and the refusal leaves both timelines independent:
  // releasing the one that refused leaves the other whole. Asserting only that
  // the call failed would pass against a binding that merged the two timelines
  // first and failed afterwards.
  {
    name: "conformance: naming_an_object_from_another_timeline_is_refused",
    run(api) {
      const mine = new api.Track({ name: "V1", kind: "Video" });
      const ours = new api.Clip({ name: "Ours" });
      mine.appendChild(ours);
      const elsewhere = new api.Track({ name: "V2", kind: "Video" });
      const theirs = new api.Clip({ name: "Theirs" });
      elsewhere.appendChild(theirs);
      conformanceForeign(api, "mine.detachChild(theirs)", () => mine.detachChild(theirs));
      mine.dispose();
      conformanceIs(elsewhere.childCount(), 1, "elsewhere.childCount()");
      conformanceIs(theirs.name, "Theirs", "theirs.name");
    },
  },
  // The scenario "a_list_drawn_from_two_timelines_is_refused".
  //
  // A call handed a list refuses one whose objects come from two timelines,
  // rather than merging them, and both timelines stay independent.
  {
    name: "conformance: a_list_drawn_from_two_timelines_is_refused",
    run(api) {
      const first = new api.Track({ name: "V1", kind: "Video" });
      const second = new api.Track({ name: "V2", kind: "Video" });
      conformanceForeign(api, "api.algorithms.flattenTracks([first, second])", () => api.algorithms.flattenTracks([first, second]));
      first.dispose();
      conformanceIs(second.name, "V2", "second.name");
    },
  },
  // The scenario "an_object_built_on_its_own_joins_the_track_it_is_appended_to".
  //
  // Upstream's `track.append(Clip("shot"))`: a clip built on its own moves into
  // the track's timeline when it is appended, and the handle the caller already
  // holds keeps working there.
  {
    name: "conformance: an_object_built_on_its_own_joins_the_track_it_is_appended_to",
    run(api) {
      const track = new api.Track({ name: "V1", kind: "Video" });
      const clip = new api.Clip({ name: "shot" });
      track.appendChild(clip);
      conformanceIs(track.childCount(), 1, "track.childCount()");
      conformanceIs(clip.name, "shot", "clip.name");
    },
  },
  // The scenario "handles_forward_through_every_move".
  //
  // A clip appended to a track, which is then appended to a timeline's stack,
  // has moved twice. The handle to it still answers, and releasing the timeline
  // it ended up in releases it too.
  {
    name: "conformance: handles_forward_through_every_move",
    run(api) {
      const clip = new api.Clip({ name: "shot" });
      const track = new api.Track({ name: "V1", kind: "Video" });
      track.appendChild(clip);
      const timeline = new api.Timeline({ name: "Cut" });
      const stack = timeline.tracks;
      if (!(stack instanceof api.Stack)) {
        throw new Error("timeline's tracks are not a stack");
      }
      stack.appendChild(track);
      conformanceIs(clip.name, "shot", "clip.name");
      conformanceIs(stack.childCount(), 1, "stack.childCount()");
    },
  },
  // The scenario "an_object_with_a_parent_is_refused_and_both_timelines_stay_whole".
  //
  // Appending a clip that is already in another timeline's track is refused
  // with the core's own status, as upstream refuses it, and the refusal moves
  // nothing: releasing the timeline the clip is in leaves the track that
  // refused it whole. A binding that moved the clip's timeline in first and let
  // the library refuse afterwards would fail the same way and have merged the
  // two, so releasing one would release both (#75).
  {
    name: "conformance: an_object_with_a_parent_is_refused_and_both_timelines_stay_whole",
    run(api) {
      const first = new api.Track({ name: "T1", kind: "Video" });
      const second = new api.Track({ name: "T2", kind: "Video" });
      const clip = new api.Clip({ name: "C" });
      first.appendChild(clip);
      conformanceRefused(api, "second.appendChild(clip)", () => second.appendChild(clip), "coreError");
      first.dispose();
      conformanceIs(second.name, "T2", "second.name");
      conformanceIs(second.childCount(), 0, "second.childCount()");
    },
  },
  // The scenario "a_stale_object_is_refused_and_both_timelines_stay_whole".
  //
  // Appending a clip whose handle has gone stale, because it was removed from
  // the timeline it was in, is refused with the stale-handle status the core
  // gives, and the refusal moves nothing: releasing that timeline leaves the
  // track that refused the clip whole. A binding that moved the stale clip's
  // timeline in first and let the library refuse afterwards would have merged
  // the two, so releasing one would release both.
  {
    name: "conformance: a_stale_object_is_refused_and_both_timelines_stay_whole",
    run(api) {
      const first = new api.Track({ name: "T1", kind: "Video" });
      const second = new api.Track({ name: "T2", kind: "Video" });
      const clip = new api.Clip({ name: "C" });
      first.appendChild(clip);
      clip.remove();
      conformanceRefused(api, "second.appendChild(clip)", () => second.appendChild(clip), "staleHandle");
      first.dispose();
      conformanceIs(second.name, "T2", "second.name");
      conformanceIs(second.childCount(), 0, "second.childCount()");
    },
  },
];

/** Fails the scenario unless two values are the same. */
function conformanceIs<T>(found: T, wanted: T, what: string): void {
  if (!Object.is(found, wanted)) {
    throw new Error(
      `${what}: expected ${JSON.stringify(wanted)}, found ${JSON.stringify(found)}`,
    );
  }
}

/** Fails the scenario unless a time is exactly `value` at `rate`. */
function conformanceTime(
  found: { readonly value: number; readonly rate: number },
  value: number,
  rate: number,
  what: string,
): void {
  if (found.value !== value || found.rate !== rate) {
    throw new Error(
      `${what}: expected ${value} at ${rate}, found ${found.value} at ${found.rate}`,
    );
  }
}

/** What `body` threw, failing the scenario if it threw nothing. */
function conformanceThrown(what: string, body: () => unknown): unknown {
  try {
    body();
  } catch (thrown) {
    return thrown;
  }
  throw new Error(`${what}: nothing was thrown`);
}

/** Insists the library refused with one status. */
function conformanceRefused(
  api: Otio,
  what: string,
  body: () => unknown,
  status: Status,
): void {
  const thrown = conformanceThrown(what, body);
  if (!(thrown instanceof api.OtioError) || thrown.status !== status) {
    throw new Error(
      `${what}: threw ${String(thrown)}, want an OtioError with status ${status}`,
      { cause: thrown },
    );
  }
}

/**
 * Insists the binding refused an object from another timeline before asking
 * the library, rather than letting the library fail.
 */
function conformanceForeign(api: Otio, what: string, body: () => unknown): void {
  const thrown = conformanceThrown(what, body);
  if (!(thrown instanceof api.OtherTimelineError)) {
    throw new Error(`${what}: threw ${String(thrown)}, want an OtherTimelineError`, {
      cause: thrown,
    });
  }
}
